<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { Plus } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { errorMessage, governanceApi } from '@/api'
import type { ID, OrgAlias, Organization } from '@/types/api'
import PageHeader from '@/components/PageHeader.vue'
import StatusTag from '@/components/StatusTag.vue'
import RemoteState from '@/components/RemoteState.vue'
const activeTab = ref('orgs')
const orgs = ref<Organization[]>([])
const aliases = ref<OrgAlias[]>([])
const loading = ref(false)
const error = ref('')
const keyword = ref('')
const orgDialog = ref(false)
const aliasDialog = ref(false)
const saving = ref(false)
const editingOrgId = ref<ID>()
const editingAliasId = ref<ID>()
const orgForm = reactive<Partial<Organization>>({ org_code: '', org_name: '', org_short_name: '', org_type: 'COLLEGE', sort_no: 1, status: 'ENABLED' })
const aliasForm = reactive<Partial<OrgAlias>>({ alias_name: '', source_name: '', org_id: undefined, confirm_status: 'PENDING' })
async function load() { loading.value = true; error.value = ''; try { const [o, a] = await Promise.all([governanceApi.organizations({ page_size: 200, keyword: keyword.value }), governanceApi.aliases({ page_size: 200, keyword: keyword.value }).catch(() => ({ items: [] as OrgAlias[], total: 0 }))]); orgs.value = o.items; aliases.value = a.items } catch (cause) { error.value = errorMessage(cause) } finally { loading.value = false } }
function openOrg(row?: Organization) { editingOrgId.value = row?.id; Object.assign(orgForm, row ? { ...row } : { org_code: '', org_name: '', org_short_name: '', org_type: 'COLLEGE', parent_id: undefined, sort_no: orgs.value.length + 1, status: 'ENABLED', lock_version: undefined }); orgDialog.value = true }
async function saveOrg() { if (!orgForm.org_code || !orgForm.org_name) { ElMessage.warning('组织代码和标准名称必填'); return } saving.value = true; try { if (editingOrgId.value) await governanceApi.updateOrganization(editingOrgId.value, orgForm); else await governanceApi.createOrganization(orgForm); ElMessage.success('组织已保存'); orgDialog.value = false; await load() } catch (cause) { ElMessage.error(errorMessage(cause)) } finally { saving.value = false } }
function openAlias(row?: OrgAlias) { editingAliasId.value = row?.id; Object.assign(aliasForm, row ? { ...row } : { alias_name: '', source_name: 'Excel 导入', org_id: undefined, confirm_status: 'PENDING', lock_version: undefined }); aliasDialog.value = true }
async function saveAlias() { if (!aliasForm.alias_name) { ElMessage.warning('别名必填'); return } if (!aliasForm.org_id) { ElMessage.warning('新建别名须先选择标准组织，再由人工确认映射'); return } if (aliasForm.confirm_status === 'CONFIRMED' && !aliasForm.org_id) { ElMessage.warning('确认别名前必须选择标准组织'); return } saving.value = true; try { if (editingAliasId.value) await governanceApi.updateAlias(editingAliasId.value, aliasForm); else await governanceApi.createAlias(aliasForm); ElMessage.success('别名映射已保存'); aliasDialog.value = false; await load() } catch (cause) { ElMessage.error(errorMessage(cause)) } finally { saving.value = false } }
onMounted(load)
</script>
<template>
  <div class="page-container"><PageHeader title="组织与别名" description="标准学院名录保持唯一，源表简称经人工确认后映射。组织停用不删除历史业务记录。"><template #actions><el-button @click="openAlias()">新增别名</el-button><el-button type="primary" @click="openOrg()"><el-icon><Plus /></el-icon>新建组织</el-button></template></PageHeader>
    <div class="filter-bar" style="margin-bottom:14px;border-radius:8px"><el-input v-model="keyword" placeholder="标准名称／简称／别名" clearable style="width:280px" @keyup.enter="load" /><el-button type="primary" plain @click="load">查询</el-button></div>
    <el-tabs v-model="activeTab" class="panel" style="padding:0 15px"><el-tab-pane :label="`标准组织（${orgs.length}）`" name="orgs" /><el-tab-pane :label="`别名映射（${aliases.length}）`" name="aliases" /></el-tabs>
    <RemoteState :loading="loading" :error="error" @retry="load"><el-table v-if="activeTab === 'orgs'" :data="orgs"><el-table-column prop="org_code" label="组织代码" width="150" class-name="mono" /><el-table-column prop="org_name" label="标准名称" min-width="220" /><el-table-column prop="org_short_name" label="简称" width="120"><template #default="{ row }">{{ row.org_short_name || '—' }}</template></el-table-column><el-table-column label="组织类型" width="130"><template #default="{ row }">{{ row.org_type === 'COLLEGE' ? '学院' : row.org_type === 'SCHOOL_DEPT' ? '校级部门' : '其他' }}</template></el-table-column><el-table-column prop="sort_no" label="排序" width="80" align="center" /><el-table-column label="状态" width="90"><template #default="{ row }"><StatusTag :status="row.status" /></template></el-table-column><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link type="primary" @click="openOrg(row)">编辑</el-button></template></el-table-column></el-table><el-table v-else :data="aliases"><el-table-column prop="alias_name" label="别名／源表名称" min-width="190" /><el-table-column prop="source_name" label="别名来源" width="150" /><el-table-column label="映射标准组织" min-width="210"><template #default="{ row }">{{ row.org_name || orgs.find(item => item.id === row.org_id)?.org_name || '尚未映射' }}</template></el-table-column><el-table-column label="确认状态" width="115"><template #default="{ row }"><StatusTag :status="row.confirm_status" /></template></el-table-column><el-table-column label="操作" width="140"><template #default="{ row }"><el-button link type="primary" @click="openAlias(row)">{{ row.confirm_status === 'PENDING' ? '人工匹配' : '编辑' }}</el-button></template></el-table-column></el-table><el-empty v-if="activeTab === 'orgs' && !orgs.length || activeTab === 'aliases' && !aliases.length" description="暂无记录" /></RemoteState>
    <el-dialog v-model="orgDialog" :title="editingOrgId ? '编辑组织' : '新建组织'" width="560px"><el-form label-width="95px"><el-form-item label="组织代码" required><el-input v-model="orgForm.org_code" :disabled="Boolean(editingOrgId)" placeholder="稳定且唯一，不以名称为外键" /></el-form-item><el-form-item label="标准名称" required><el-input v-model="orgForm.org_name" /></el-form-item><el-form-item label="组织简称"><el-input v-model="orgForm.org_short_name" /></el-form-item><el-form-item label="组织类型"><el-select v-model="orgForm.org_type" style="width:100%"><el-option label="学院" value="COLLEGE" /><el-option label="校级部门" value="SCHOOL_DEPT" /><el-option label="其他" value="OTHER" /></el-select></el-form-item><el-form-item label="上级组织"><el-select v-model="orgForm.parent_id" clearable style="width:100%"><el-option v-for="org in orgs.filter(item => item.id !== editingOrgId)" :key="org.id" :value="org.id" :label="org.org_name" /></el-select></el-form-item><el-form-item label="排序号"><el-input-number v-model="orgForm.sort_no" :min="1" /></el-form-item><el-form-item label="状态"><el-radio-group v-model="orgForm.status"><el-radio value="ENABLED">启用</el-radio><el-radio value="DISABLED">停用</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="orgDialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="saveOrg">保存</el-button></template></el-dialog>
    <el-dialog v-model="aliasDialog" title="组织别名人工匹配" width="560px"><el-alert title="数据产业学院与大数据产业学院不得未经确认自动视为同一主体。" type="warning" :closable="false" style="margin-bottom:15px" /><el-form label-width="100px"><el-form-item label="别名原文" required><el-input v-model="aliasForm.alias_name" /></el-form-item><el-form-item label="别名来源"><el-input v-model="aliasForm.source_name" /></el-form-item><el-form-item label="标准组织"><el-select v-model="aliasForm.org_id" filterable clearable style="width:100%"><el-option v-for="org in orgs" :key="org.id" :value="org.id" :label="`${org.org_name}（${org.org_code}）`" /></el-select></el-form-item><el-form-item label="确认状态"><el-radio-group v-model="aliasForm.confirm_status"><el-radio value="PENDING">待确认</el-radio><el-radio value="CONFIRMED">确认映射</el-radio><el-radio value="REJECTED">拒绝映射</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="aliasDialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="saveAlias">保存映射</el-button></template></el-dialog>
  </div>
</template>
